#include <iiActorObject/Object3DEditor.h>

iiActorObject::SkeletonEnvelopeOptions inference;
inference.radiusRatio = .25;
inference.minimumRadius = .001; // 오브젝트 좌표 단위에 맞게 지정
iiActorObject::SurfaceBindOptions binding;
binding.unreachable = iiActorObject::SurfaceBindUnreachable::Euclidean;
auto result = editor.bindSurfaceWeightsFromSkeleton(meshIndex, inference, binding);
// result.inference.envelopes는 편집 또는 재사용할 수 있는 값이다.
// result.binding은 적용·미도달·대체 점 수를 구분한다.
